param([string]$ProjectRoot=(Join-Path $PSScriptRoot '..'),[string]$BuildRoot='',[ValidateRange(1,180)][double]$DurationMinutes=60,[ValidateRange(5,120)][int]$CycleSeconds=60,[string]$RunRoot='')
$ErrorActionPreference='Stop';$ProjectRoot=[IO.Path]::GetFullPath($ProjectRoot);if(!$BuildRoot){$BuildRoot=Join-Path $ProjectRoot out/release};$BuildRoot=[IO.Path]::GetFullPath($BuildRoot)
if(!(Test-Path -LiteralPath (Join-Path $BuildRoot plugins/tts/runtime.json))){throw 'Configured local Mei assets are required.'};Add-Type -Path (Join-Path $PSScriptRoot PrivateDesktop.cs)
if(!$RunRoot){$RunRoot=Join-Path $ProjectRoot ('artifacts/speech-soak-'+[Guid]::NewGuid().ToString('N'))};$RunRoot=[IO.Path]::GetFullPath($RunRoot);if(Test-Path (Join-Path $RunRoot progress.json)){throw 'Choose an unused test directory.'};New-Item -ItemType Directory -Force $RunRoot|Out-Null
$service=$null;$desktop=$null;$provider=$null;$cycles=0;$checks=0;$restarts=0;$queued=0;$interruptions=0;[double]$maximumMemory=0;$started=[DateTime]::UtcNow;$finish=$started.AddMinutes($DurationMinutes)
$env:HIBERNATION_SESSION_KEY='mei-soak-fixture';$env:TEMP=Join-Path $RunRoot tmp;$env:TMP=$env:TEMP;New-Item -ItemType Directory -Force $env:TEMP|Out-Null
function Check($Value,$Name){if(!$Value){throw "CHECK FAILED: $Name"};$script:checks++}
function Wait-For([scriptblock]$Probe,$Name,[int]$Seconds=40){$end=[DateTime]::UtcNow.AddSeconds($Seconds);while([DateTime]::UtcNow-lt$end){if(& $Probe){return};Start-Sleep -Milliseconds 70};throw "TIMEOUT $Name"}
function Api($Path,$Data=$null){$a=@{Uri=$script:origin+$Path;Headers=@{Authorization='Bearer mei-soak-fixture'};TimeoutSec=10};if($null-ne$Data){$a.Method='Post';$a.ContentType='application/json';$a.Body=[Text.Encoding]::UTF8.GetBytes(($Data|ConvertTo-Json -Depth 40 -Compress))};Invoke-RestMethod @a}
function Plan($Texts){$responses=@($Texts|ForEach-Object {@{response=@{version=1;kind='reply';text=$_;calls=@();presentation=@{speech=$true;bubble=$true}}}});$plan=@{nonce=[Guid]::NewGuid().ToString('N');responses=$responses}|ConvertTo-Json -Depth 20 -Compress;[IO.File]::WriteAllText((Join-Path $RunRoot provider/plan.next),$plan,[Text.UTF8Encoding]::new($false));[IO.File]::Move((Join-Path $RunRoot provider/plan.next),(Join-Path $RunRoot provider/plan.json),$true)}
function Message($Text){$null=Api '/api/message' @{request_id=[Guid]::NewGuid().ToString('N');text=$Text};Wait-For {!(Api '/api/chat').busy} 'local synthetic reply';$chat=Api '/api/chat';Check (!$chat.call_failed) 'synthetic dialogue completes';return $chat.messages[-1].id}
function Voice-Status{$null=Api '/api/plugin/test' @{tool='speech.status';args=@{}};Wait-For {$script:receipt=Api '/api/plugin/result';$script:receipt.state-in@('succeeded','failed')} 'voice status';Check $receipt.result.ok 'voice status receipt';return $receipt.result.result}
function Snapshot-Plugin($Name){@((Api '/api/capabilities').plugins|Where-Object id -eq $Name)[0].current}
function Start-Backend{Remove-Item (Join-Path $RunRoot ready.json) -ErrorAction SilentlyContinue;$script:desktop=[PrivateDesktop]::new((Join-Path $BuildRoot hibernation-agent.exe),(Join-Path $RunRoot config.json),(Join-Path $RunRoot ready.json),$ProjectRoot);$script:service=$desktop.Child;Wait-For {if($service.HasExited){throw 'speech fixture exited'};Test-Path (Join-Path $RunRoot ready.json)} 'private speech desktop';$script:origin='http://127.0.0.1:'+((Get-Content (Join-Path $RunRoot ready.json) -Raw|ConvertFrom-Json).port)}
function Stop-Backend{$null=Api '/api/shutdown' @{};Check ($service.WaitForExit(15000)-and$service.ExitCode-eq0) 'speech backend closes cleanly';$desktop.Dispose();$script:desktop=$null}
function Progress($Status,$ErrorCode=''){$process=$null;if($service-and!$service.HasExited){$service.Refresh();$process=$service};$value=@{status=$Status;error=$ErrorCode;startedUtc=$started.ToString('O');plannedEndUtc=$finish.ToString('O');updatedUtc=[DateTime]::UtcNow.ToString('O');elapsedMinutes=([DateTime]::UtcNow-$started).TotalMinutes;cycles=$cycles;checks=$checks;restarts=$restarts;queuedCases=$queued;interruptions=$interruptions;maxPrivateMiB=$maximumMemory;privateMiB=if($process){[math]::Round($process.PrivateMemorySize64/1MB,2)}else{0};handles=if($process){$process.HandleCount}else{0};gdi=if($process){[PrivateDesktop]::GetGuiResources($process.Handle,0)}else{0};root=$RunRoot;runtimeSha=(Get-FileHash (Join-Path $BuildRoot hibernation-agent.exe) -Algorithm SHA256).Hash};$value|ConvertTo-Json -Depth 7|Set-Content (Join-Path $RunRoot progress.json) -Encoding utf8;$value|ConvertTo-Json -Depth 7 -Compress|Add-Content (Join-Path $RunRoot samples.jsonl) -Encoding utf8}
try{
 $providerRoot=Join-Path $RunRoot provider;$provider=Start-Process (Join-Path $BuildRoot Hibernation_TestProvider.exe) -ArgumentList ('"'+$providerRoot+'" 43200') -WindowStyle Hidden -PassThru -RedirectStandardOutput (Join-Path $RunRoot provider.log) -RedirectStandardError (Join-Path $RunRoot provider-error.log);Wait-For {Test-Path (Join-Path $providerRoot port)} 'local provider';$fixture='http://127.0.0.1:'+(Get-Content (Join-Path $providerRoot port))
 $cfg=Get-Content (Join-Path $ProjectRoot config/example.json) -Raw|ConvertFrom-Json -AsHashtable;$cfg.dataRoot=Join-Path $RunRoot data;$cfg.characterRoot=Join-Path $ProjectRoot character;$cfg.uiRoot=Join-Path $ProjectRoot ui;$cfg.pluginRoot=Join-Path $BuildRoot plugins;$cfg.frontend=@{startupAnimation=$false;reducedMotion=$true};$cfg.solitudeIntervalMs=604800000;$cfg.idleBeforeSolitudeMs=86400000;$cfg.maxStartsPerHour=1000;$cfg.review=@{enabled=$false};$cfg.profiles+=@{id='fixture';label='Synthetic speech role';enabled=$true;protocol='chat-completions';origin=$fixture;basePath='/v1';model='fixture-model';timeoutMs=5000;maxOutputTokens=2048};$cfg.plugins=@{widget=@{enabled=$true;roam=$false;reducedMotion=$true;reactionCacheEnabled=$false;bubbleMaxCharacters=20};tts=@{enabled=$true;backend='kana';volume=0;speed=1;autoSpeak=$true;maxSeconds=25}};$cfg|ConvertTo-Json -Depth 35|Set-Content (Join-Path $RunRoot config.json) -Encoding utf8;Set-Content (Join-Path $RunRoot '.synthetic-speech-soak') 'No production conversations or audible output.'
 Start-Backend;$null=Api '/api/model' @{id='fixture'};Progress 'running';$phrases=@('窗边留着一点光。桌面的纸星还在。今天先把话慢慢说完。','风没有把那片叶子带走。我先待在这里，看一会儿它的边缘。','刚才那一小段话已经留下了。接下来的句子，也会等到自己的声音。','这次不急着走过去。等前一句说完，再把下一句放出来。')
 while([DateTime]::UtcNow-lt$finish){if(Test-Path (Join-Path $RunRoot stop)){Progress 'stopped';break};$at=[DateTime]::UtcNow;$cycles++;$text=$phrases[($cycles-1)%$phrases.Count];$queueCase=$cycles%5-eq0;$pauseCase=$cycles%10-eq0;Plan @($text,'这是后面排队的短句，也需要等自己的声音。');$id=Message ('合成语音检查 '+$cycles);$watch=[Diagnostics.Stopwatch]::StartNew();Wait-For {$script:clock=(Api '/api/playback').replies.$id;if($clock.state-eq'waiting'){Check ($clock.visible_characters-eq0) 'waiting speech never reveals text'};return $clock.state-in@('speaking','completed','failed')} 'real Mei playback begins';Check ($clock.state-ne'failed') 'Mei synthesis succeeds';$firstMs=$watch.ElapsedMilliseconds;$ids=@($id)
  if($queueCase){$second=Message '排队检查';$ids+=@($second);$queued++;$clock=(Api '/api/playback').replies.$second;Check ($clock.state-eq'waiting'-and$clock.visible_characters-eq0) 'queued speech keeps its own hidden text'}
  if($pauseCase){$null=Api '/api/control' @{paused=$true};Wait-For {!(Snapshot-Plugin tts).active} 'pause stops actual voice';$before=(Snapshot-Plugin tts).started_count;$null=Api '/api/control' @{paused=$false};Start-Sleep -Milliseconds 500;Check ((Snapshot-Plugin tts).started_count-eq$before) 'resume does not replay old voice';$interruptions++}
  else{$visible=@{};Wait-For {$states=(Api '/api/playback').replies;$done=$true;foreach($key in $ids){$value=$states.$key;if($value.state-eq'failed'){throw 'Mei playback failed'};if($value.state-in@('waiting','speaking')){$done=$false};$count=[long]$value.visible_characters;if($visible.ContainsKey($key)){Check ($count-ge$visible[$key]) 'audio character clock remains monotonic'};$visible[$key]=$count;if($value.state-eq'speaking'){Check ($value.position_seconds-le$value.duration_seconds+.1) 'played audio never outruns available segment duration'}};return $done} 'Mei segmented replies finish' 70}
  $voice=Voice-Status;Check ($voice.backend-eq'kana'-and$voice.volume-eq0-and$voice.output.assessment.heard_confirmed-eq$false) 'real local voice remains silent and makes no hearing claim';Check ($voice.maximum_buffered_segments-le3-and$voice.last_underruns-eq0) 'segment prefetch remains bounded without underruns';Check (@(Get-ChildItem -LiteralPath (Join-Path $cfg.dataRoot runtime/speech) -File -ErrorAction SilentlyContinue).Count-eq0) 'transient speech inputs are removed';Check ((Api '/api/chat').health-eq'ok') 'speech owner remains healthy';$service.Refresh();$maximumMemory=[math]::Max($maximumMemory,[math]::Round($service.PrivateMemorySize64/1MB,2));@{cycle=$cycles;firstAudioMs=$firstMs;segments=$voice.last_stream_segments;buffered=$voice.maximum_buffered_segments;underruns=$voice.last_underruns;workerStarts=$voice.kana_worker_starts;duration=$voice.last_duration_seconds}|ConvertTo-Json -Compress|Add-Content (Join-Path $RunRoot voice.jsonl) -Encoding utf8
  if($cycles%15-eq0){Stop-Backend;Start-Backend;$restarts++;Start-Sleep -Milliseconds 400;Check ((Snapshot-Plugin tts).started_count-eq0) 'restart never replays historical dialogue'};Progress 'running';while([DateTime]::UtcNow-lt$at.AddSeconds($CycleSeconds)-and[DateTime]::UtcNow-lt$finish){Start-Sleep -Milliseconds 1000}
 };if([DateTime]::UtcNow-ge$finish){Progress 'completed'}
}catch{Progress 'failed' $_.Exception.GetType().Name;throw}finally{if($service-and!$service.HasExited){try{Stop-Backend}catch{}};if($desktop){$desktop.Dispose()};if($provider-and!$provider.HasExited){$provider.Kill();$provider.WaitForExit(5000)|Out-Null}}


